public class C
{
    public static void Main()
    {
        var tuple = (1, 2);

        tuple.Item1 = 3;
    }
}
namespace System
{
    public readonly struct ValueTuple<T1, T2>
    {
        public readonly T1 Item1;
        public readonly T2 Item2;

        public ValueTuple(T1 item1, T2 item2)
        {
            this.Item1 = item1;
            this.Item2 = item2;
        }
    }
}

